WITH matched_keys AS (SELECT id FROM payments INTERSECT ALL SELECT id FROM payments WHERE method IN ('promptpay', 'paypal', 'cash')), reconciled AS (SELECT s.* FROM payments s JOIN matched_keys k ON s.id = k.id) SELECT s.id, s.order_id, s.amount, s.status, (SELECT SUM(o2.unit_price) FROM order_items o2 WHERE o2.order_id = s.order_id) AS sum_order_item_unit_price FROM reconciled s;
